func main() {
	a := make(chan string, 1)
	b := make(chan string, 1)
	counts := map[string]int{}
	for i := 0; i < 10000; i++ {
		a <- "a"
		b <- "b"
		select {
		case v := <-a: // listed first
			counts[v]++
			<-b
		case v := <-b:
			counts[v]++
			<-a
		}
	}
	fmt.Println("a:", counts["a"], "b:", counts["b"])
}

func FetchAll(ctx context.Context, urls []string, limit int, fetch func(context.Context, string) error) {
	sem := make(chan struct{}, limit)
	var wg sync.WaitGroup
	for _, u := range urls {
		select {
		case sem <- struct{}{}:
		case <-ctx.Done():
			continue
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { <-sem }()
			fetch(ctx, u)
		}()
	}
	wg.Wait()
}

for i, u := range urls {
